 	case StatusOK:
 		return "StatusOK"
 	case StatusRecoverableError:
 		return "StatusRecoverableError"
 	case StatusPermanentError:
 		return "StatusPermanentError"
 	case StatusFatalError:
 		return "StatusFatalError"
 	case StatusStopping:
 		return "StatusStopping"
 	case StatusStopped:
